// config.js - Secure Configuration (DO NOT EDIT THIS FILE DIRECTLY)
(function() {
  // ========== LAYER 1: BASE64 ENCODED PARTS ==========
  const _encodedParts = [
      'aHR0cDovLw==',           
      'c2xrYnVsbGlvbi5jb206',    
      'MTAwMDE='                  
  ];
  
  // ========== LAYER 2: XOR ENCRYPTION KEY ==========
  const _xorKey = 0x2A; // 42 - This is our encryption key
  
  // ========== LAYER 3: OBFUSCATED CLIENT ID ==========

  const _clientReverse = 'kls';
  
  // Function to decode base64
  function _decodeBase64(str) {
      try {
          return atob(str);
      } catch(e) {
          return '';
      }
  }
  
  // Function to XOR decode (encrypt/decrypt)
  function _xorDecode(str) {
      let result = '';
      for (let i = 0; i < str.length; i++) {
          result += String.fromCharCode(str.charCodeAt(i) ^ _xorKey);
      }
      return result;
  }
  
  // Function to reverse a string
  function _reverseString(str) {
      return str.split('').reverse().join('');
  }
  
  // Build the complete URL
  function _buildUrl() {
      try {
          const httpPart = _decodeBase64(_encodedParts[0]);
          const domainPart = _decodeBase64(_encodedParts[1]);
          const portPart = _decodeBase64(_encodedParts[2]);
          return httpPart + domainPart + portPart;
      } catch(e) {
          return ''; // Return empty if decoding fails
      }
  }
  
 
  function _getClientId() {
      return _reverseString(_clientReverse);
  }
  
  // Make config available globally with a hidden name
  window.__SECURE_GOLD = {
      url: _buildUrl(),
      client: _getClientId(),
      transports: ['websocket'],
      version: '2.0.1',
      timestamp: Date.now()
  };
  
  // Optional: Store verification in localStorage
  try {
      if (!localStorage.getItem('__sg_verified')) {
          localStorage.setItem('__sg_verified', 'true');
      }
  } catch(e) {
      // Silent fail
  }
})();